// Moving Average from Data Stream using Sliding Window Queue
struct MovingAverage {
    var queue = AnimatedQueue<Double>()
    let maxSize: Int
    var runningSum = 0.0

    mutating func next(_ val: Double) -> Double {
        if queue.count >= maxSize {
            if let evicted = queue.dequeue() {
                runningSum -= evicted
            }
        }
        queue.enqueue(val)
        runningSum += val
        return runningSum / Double(queue.count)
    }
}

var filter = MovingAverage(maxSize: 3)
let stream = [1.0, 10.0, 3.0, 5.0]
for v in stream {
    _ = filter.next(v)
}
